import json
with open('/app/resources/treasury_bulletin_2011_09.json', 'r') as f:
    data = json.load(f)

# Print keys to understand structure
def print_keys(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                print_keys(v, indent + 2)
    elif isinstance(d, list) and len(d) < 10:
        for i, item in enumerate(d[:3]):
            print(' ' * indent + f'[{i}]')
            print_keys(item, indent + 2)

print_keys(data)
